INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, "2025/01/31 12:00:00", 1000001, "2030/01/01 14:59:59", 62, 1, 0.0, "カリン", 1, 3.414, 190805, "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください", -416.5, 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, "2025/01/31 12:00:00", 1000002, "2030/01/01 14:59:59", 62, 2, 0.0, "カリン", 1, 3.099, 190805, "ミッションをクリアして、\n報酬をゲットしましょう！", -416.5, 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, "2025/01/31 12:00:00", 1000003, "2030/01/01 14:59:59", 63, 3, 0.0, "カリン", 1, 2.801, 190805, "受け取ることができる\n報酬があるようです\n確認してみてください", -416.5, 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, "2025/01/31 12:00:00", 1000004, "2030/01/01 14:59:59", 63, 4, 0.0, "カリン", 1, 0.0, 190805, "報酬がもらえますよ！\nチェックしてみてください", -416.5, 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, "2025/01/31 12:00:00", 1000005, "2030/01/01 14:59:59", 64, 5, 0.0, "カリン", 1, 2.12, 190805, "ギルド管理協会です！\nイベント報酬券をお持ちでしたら、様々なアイテムと交換できますよ", -363.0, 1);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, "2025/01/31 12:00:00", 1000006, "2030/01/01 14:59:59", 64, 6, 0.0, "カリン", 1, 1.68, 190805, "お疲れさまです！\nこちらでイベント報酬券とアイテムを交換することができますよ", -363.0, 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, "2025/01/31 12:00:00", 1000007, "2030/01/01 14:59:59", 64, 7, 0.0, "カリン", 1, 2.33, 190805, "いつもありがとうございます！\n報酬交換ですか？\nでは、イベント報酬券とお引き換えいたしますね", -363.0, 1);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (3, "2025/01/31 12:00:00", 1020101, "2030/01/01 14:59:59", 61, 101, -6.0, "ラビリスタ", 10201, 5.18, 133701, "今度の敵は、アタシにとっても\n放ってはおけない存在だ\n少年、アタシも全力で行くからさ\n一緒に守ろう、この世界を", -285.0, 7);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, "2025/01/31 12:00:00", 1020102, "2030/01/01 14:59:59", 61, 201, -2.0, "クリスティーナ", 10201, 8.77, 133901, "退屈の吹き飛ぶような\n戦いの気配がするなぁ坊や\nさっさとワタシをそこへ連れてゆけ\n世界も守ってやるさ、ついでにな", -285.0, 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (6, "2025/01/31 12:00:00", 1020103, "2030/01/01 14:59:59", 61, 301, 0.0, "ネネカ", 10201, 15.5, 133801, "おや、私の力が必要……と？\nグレゴールが手伝うそうですよ\n私は戦わないのか、という顔ですね\n……考えておきます", -285.0, 1);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, "2025/02/28 12:00:00", 1020201, "2030/01/01 14:59:59", 61, 101, 0.0, "ランファ", 10202, 9.061, 134301, "わたしだけの歌…\n一緒に、探してくれる…？\nあなたがいれば…\nもっとがんばれるから…", -285.0, 5);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, "2025/02/28 12:00:00", 1020202, "2030/01/01 14:59:59", 61, 201, 0.0, "チカ", 10202, 7.699, 134401, "同じ唱喚士として、仲間として\n私にできることをします\n…これも、あなたが\n背中を押してくれたおかげですよ", -285.0, 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, "2025/03/31 12:00:00", 1020301, "2030/01/01 14:59:59", 61, 101, 0.0, "アオイ", 10203, 8.595, 134601, "世界の平和が私とクローチェさんに\nかかってるんですよね？\nぼっちには過大すぎる期待ですけど\nふ、二人でなら背負ってみせます！", -285.0, 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, "2025/03/31 12:00:00", 1020302, "2030/01/01 14:59:59", 61, 201, 0.0, "クローチェ", 10203, 7.758, 134501, "新しく手に入れたこの翼で…\nナイトさんがどこにいたって\nわたし、駆けつけちゃいますよっ！\nクローチェ・エアリアル発進ですっ", -285.0, 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, "2025/04/30 12:00:00", 1020401, "2030/01/01 14:59:59", 61, 101, 0.0, "ルイズマリー", 10204, 7.0, 132302, "今日はダーリンとの初デート♪\n二人でショッピングして、その後は\n…って私、指名手配されてる！？\nちょ、た…助けてダーリン～！！", -285.0, 6);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, "2025/04/30 12:00:00", 1020402, "2030/01/01 14:59:59", 61, 201, 0.0, "イロハ", 10204, 7.904, 132402, "ルイちゃんのおばあちゃん優しくて\nいつもにこにこで、イロハ大好き♪\nでも一番好きなのは、角がすっごく\n大きくてかっこいいとこなんだ～♪", -285.0, 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (4, "2025/04/30 12:00:00", 1020403, "2030/01/01 14:59:59", 61, 301, 0.0, "ソノ", 10204, 8.487, 132502, "ノゾミちゃんのおかげで売上が安定\nしてきたのに、臨時休業、痛すぎる\n…ま、ルイちゃんのために\n一肌脱ぐか。行くよイロハ～", -285.0, 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, "2025/05/31 12:00:00", 1020502, "2030/01/01 14:59:59", 61, 101, 0.0, "カノン", 10205, 8.763, 134901, "ヲ～ッホッホ♪\nあたくし様と同じお空気を吸える\nお幸運を噛みしめなさいですわ～♪\nヲ～ッホッホッホ～♪", -285.0, 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, "2025/05/31 12:00:00", 1020503, "2030/01/01 14:59:59", 61, 201, 0.0, "ツムギ", 10205, 6.417, 134801, "いきますよ騎士さん！\nカノンさんと力を合わせて…力を…\n…本当にあの人なんなんです？\nこれまでになく不安なんですけど！", -285.0, 3);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (3, "2025/06/30 12:00:00", 1020601, "2030/01/01 14:59:59", 61, 101, 0.0, "エリス", 10206, 10.335, 135001, "『願いが叶う海岸』か…怪しい\nだというのに、阿賀斗紫布菜たちは\n呑気に戯れている…見ていられない\n騎士クンは、わたしが守ってみせる", -285.0, 7);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, "2025/06/30 12:00:00", 1020602, "2030/01/01 14:59:59", 61, 201, 0.0, "シェフィ", 10206, 6.281, 135101, "せっかくの夏休みなんだし\nたまにはビーチでゆっくりしましょ\n…え、もしかしてこの夏もあんまり\n休めなかったりする感じなの？", -285.0, 4);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, "2025/06/30 12:00:00", 1020603, "2030/01/01 14:59:59", 61, 301, 0.0, "プレシア", 10206, 12.244, 135201, "いっぱい。たべて\nおおきく。なると\nせーぎ。まもれる。はず\nお兄。いっしょに。スイカ。たべよ", -285.0, 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, "2025/07/31 12:00:00", 1020701, "2030/01/01 14:59:59", 61, 101, 0.0, "クリア", 10207, 6.339, 135301, "ひと夏の冒険のはじまりです！\nアネモネさんも楽しんでくれたら\n…できれば、もう少し\n仲良くなれたらうれしいな…", -285.0, 8);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (7, "2025/07/31 12:00:00", 1020702, "2030/01/01 14:59:59", 61, 201, 0.0, "アネモネ", 10207, 8.184, 135401, "─幻の花…\n本当にあるのか謎─ですけど\n探すくらいは、\n付き合ってもいいです", -285.0, 9);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (9, "2025/08/31 12:00:00", 1020801, "2030/01/01 14:59:59", 61, 101, 0.0, "アイラ", 10208, 3.906, 129101, "あははっ！　笑う門には福来る！\n笑ってればきっと、複製世界にも\n未来はやってくるって信じてる！\nそうだよね、シナツちゃん！", -285.0, 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, "2025/08/31 12:00:00", 1020802, "2030/01/01 14:59:59", 61, 201, 0.0, "シナツ", 10208, 14.465, 129201, "繰り返されるリセットの先の未来\n何度願っても手に入らなかった未来\n…でも、私は諦めない。絶対にだ\nキミも同じだろ…アイラ？", -285.0, 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (4, "2025/08/31 12:00:00", 1020803, "2030/01/01 14:59:59", 61, 301, 0.0, "ヒヨリ", 10208, 8.662, 100101, "アイラの世界のみんなも、\n一生懸命生きてるんだ…！\n…なのに、世界の危機だなんて！\nあたし、絶対、絶対力になるよ！", -285.0, 3);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, "2025/08/31 12:00:00", 1020804, "2030/01/01 14:59:59", 61, 401, 0.0, "レイ", 10208, 10.915, 100301, "シナツ…もう一人の私\n彼女が大切にしている世界を\n絶対に終わらせはしない…！\n彼女と笑い合える未来のために！", -285.0, 3);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, "2025/09/30 12:00:00", 1020901, "2030/01/01 14:59:59", 61, 101, 0.0, "ユキノ", 10209, 6.042, 135802, "あ、ど、ども…\nあ、あんま見ねぇでくれっと\nその、恥ずかしくて…\n体が熱くなって、溶けちまう…", -285.0, 7);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (4, "2025/09/30 12:00:00", 1020902, "2030/01/01 14:59:59", 61, 201, 0.0, "サツキ", 10209, 9.402, 135903, "なんで俺が幽霊に…意味不明だ\nこれじゃ死んでも死にきれねェ\n悪ィがこれも何かの縁だ、\nよろしく頼むぜ騎士公", -285.0, 1);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (8, "2025/09/30 12:00:00", 1020903, "2030/01/01 14:59:59", 61, 301, 0.0, "ルルィ", 10209, 8.16, 136902, "う、うじゅる…\nサツキ姉しゃまを助けるためにも\nまずは、腹ごしらえでしゅね…！\nタコ焼き、召し上がってくだしゃい", -285.0, 1);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (3, "2025/10/31 12:00:00", 1021001, "2030/01/01 14:59:59", 61, 101, 0.0, "カスミ", 10210, 5.0, 137401, "ひさしぶりのジオ・ゲヘナ\n歓迎パーティーで起きた殺人事件！\nランドソルの名探偵の名にかけて\n解き明かしてみせようじゃないか！", -285.0, 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (4, "2025/10/31 12:00:00", 1021002, "2030/01/01 14:59:59", 61, 201, 0.0, "アラクネ", 10210, 8.12, 136001, "…わたしはどこの誰なのでしょう\nどこから来てどこへ行くのでしょう\nこの事件の真相が分かれば、\n何かが掴めるような気がいたします", -285.0, 1);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (4, "2025/10/31 12:00:00", 1021003, "2030/01/01 14:59:59", 61, 301, 0.0, "ナーナ", 10210, 6.386, 136202, "ナーナ、すいりとかろんぱとか、\nむずかしくてわかんないけど…\nお友だちとドーナツのためならっ\nせーいっぱいがんばるよっ！", -285.0, 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (3, "2025/11/30 12:00:00", 1021101, "2030/01/01 14:59:59", 61, 101, 0.0, "ユイ", 10211, 7.438, 136402, "騎士クンに想いを伝えたい…だから\nミソラちゃん、わたしがんばるね！\n…あれ？　わたし、なんでこんなに\n必死になってるんだろう…？", -285.0, 4);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, "2025/11/30 12:00:00", 1021102, "2030/01/01 14:59:59", 61, 201, 0.0, "ミソラ", 10211, 8.35, 136302, "騎士さんとのデートはわたしに\nお任せです★　なのでユイさんは\n安心して計画に専念して…たくさん\nドキドキしちゃってくださいね", -285.0, 5);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, "2025/12/31 12:00:00", 1021201, "2030/01/01 14:59:59", 61, 101, 0.0, "シズル", 10212, 5.0, 136501, "新しい年がやってくるね！\nお正月の料理も飾りつけも、\nお姉ちゃんにお任せだよ♪\nみんなで楽しく新年を迎えよう！", -285.0, 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, "2025/12/31 12:00:00", 1021202, "2030/01/01 14:59:59", 61, 201, 0.0, "リノ", 10212, 5.25, 137902, "おうちの掃除もトラブルも、 \n世界を揺るがす大ピンチも！\n今年のことは今年のうちに \nサッサと片付けちゃいますっ！", -285.0, 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, "2025/12/31 12:00:00", 1021203, "2030/01/01 14:59:59", 61, 301, 0.0, "ラビリスタ", 10212, 7.5, 106801, "年の瀬はギルドマスターも\nつい駆け回っちゃう忙しい時期だ！\n一年いろいろあったけど\nお互いイイ年を迎えよう、少年！", -285.0, 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, "2026/01/31 12:00:00", 1021301, "2030/01/01 14:59:59", 61, 101, 0.0, "ライラエル", 10213, 8.204, 126501, "漂う異国の料理の香り…それだけで\n世界中を旅した気分に浸れますね\nふふ、ほらクローチェ\nあまりはしゃぎすぎないように…♪", -285.0, 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, "2026/01/31 12:00:00", 1021302, "2030/01/01 14:59:59", 61, 201, 0.0, "ネフィ＝ネラ", 10213, 7.176, 129701, "異界の姫君と煮炊きにて競い合う…\n感奮興起、いとをかし\n華やかなる祭典と相成るよう、一肌\n脱がせていただきとう存じまする", -285.0, 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, "2026/01/31 12:00:00", 1021303, "2030/01/01 14:59:59", 61, 301, 0.0, "ヴァイオレット", 10213, 8.602, 133101, "『ビストロプリンセス』のために\n料理の特訓を重ねてまいりました\nこの料理で騎士様の…い、いえ\n皆様の心とお腹を満たしますわ！", -285.0, 5);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, "2026/02/06 12:00:00", 1021304, "2030/01/01 14:59:59", 61, 102, 0.0, "ライラエル", 10213, 10.14, 138101, "多様な味わいが織りなすハーモニー\nそれこそが我が国の矜持です\nもしもそれを乱すようであれば\nわたしも優しくはありませんよ？", -285.0, 3);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, "2026/02/06 12:00:00", 1021305, "2030/01/01 14:59:59", 61, 202, 0.0, "ネフィ＝ネラ", 10213, 10.152, 138201, "煉獄の穢土にてひと際輝く民草の心\n此れを守護りまするがわっちの責務\n如何な困難待ち受けようと\n不退転の矜持に揺らぎはありんせん", -285.0, 7);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (4, "2026/02/06 12:00:00", 1021306, "2030/01/01 14:59:59", 61, 302, 0.0, "ヴァイオレット", 10213, 9.688, 138001, "裏世界の皆様は危機を脱し、\n残るはランドソルの皆様のみ…\n彼らを救い出すために、どうか…\nお立ち下さいペコリーヌ姫…！", -285.0, 3);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, "2026/02/12 12:00:00", 1021307, "2030/01/01 14:59:59", 61, 401, 0.0, "ペコリーヌ", 10213, 5.928, 138301, "みなさん、お待たせしちゃいました\nペコリーヌ、完全復活です☆\nみなさんの食卓を守るため\nもう二度と、わたしはめげません！", -285.0, 1);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (4, "2026/02/28 12:00:00", 1021401, "2030/01/01 14:59:59", 61, 101, 0.0, "ワカナ", 10214, 9.19, 138702, "成行きで参加することになっちゃっ\nた尻相撲大会。ううっ、恥ずかしい\nけどやるしかないよね。…騎士さん\nいっぱい応援してくださいね？", -285.0, 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, "2026/02/28 12:00:00", 1021402, "2030/01/01 14:59:59", 61, 201, 0.0, "シオリ", 10214, 8.724, 138802, "「お姉ちゃんを守れる自分になる」\nあの日の約束、今こそ果たしてみせ\nます。例えお姉ちゃんに背くことに\nなっても。例えそれが尻相撲でも！", -285.0, 3);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (4, "2026/03/31 12:00:00", 1021501, "2030/01/01 14:59:59", 61, 101, 0.0, "グレイス", 10215, 7.758, 138902, "私がへんたいふしんしゃさんって…\nただ生きているだけなのに、ひどい\n…まぁ死んでるんですけど…とか\n言ってる暇もない感じですか？", -285.0, 1);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (6, "2026/03/31 12:00:00", 1021502, "2030/01/01 14:59:59", 61, 201, 0.0, "キョウカ", 10215, 6.375, 139002, "あの、助けてください！\n私がへんたいふしんしゃさんに\nなっちゃったみたいなんです…！\nどういう意味かは私もわかりません", -285.0, 4);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (6, "2026/03/31 12:00:00", 1021503, "2030/01/01 14:59:59", 61, 301, 0.0, "ルルィ", 10215, 6.173, 136902, "ましゃか、グレイス姉しゃまたちが\nへんたいふしんしゃさんだなんて…\n騎士しゃん。あたちたちも協力ちて\n二人の破滅エンドを回避ちましょう", -285.0, 1);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (6, "2026/04/30 12:00:00", 1021601, "2030/01/01 14:59:59", 61, 101, 0.0, "ミホ", 10216, 4.202, 139202, "違う世界に来ちゃうし、\n驚きの連続だけど…\nわたしも精いっぱい頑張ります！\nアストルムのみんなと一緒に！", -285.0, 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (6, "2026/04/30 12:00:00", 1021602, "2030/01/01 14:59:59", 61, 201, 0.0, "マホ", 10216, 2.842, 139302, "想定外の事象が発生したな…だが\nいかなる苦境も切り抜けてみせる\nいつもの自分とは違う姿になっても\nわたしはわたし、西住流だ", -285.0, 1);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (4, "2026/04/30 12:00:00", 1021603, "2030/01/01 14:59:59", 61, 301, 0.0, "エリカ", 10216, 4.598, 139402, "何でこんなことになっているのか\n全然わからないけど、迷ってる暇は\nないわ。黒森峰の次期隊長として、\n前進あるのみ！　これも戦車道よ！", -285.0, 1);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (4, "2026/05/31 12:00:00", 1021701, "2030/01/01 14:59:59", 61, 101, 0.0, "リリ", 10217, 6.533, 125802, "わたくしたちの悲願は、ロストさせ\nてしまった方々をお助けすること…\nそのためなら、どのような辛苦にも\n耐え抜いてみせます…！", -285.0, 3);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (3, "2026/05/31 12:00:00", 1021702, "2030/01/01 14:59:59", 61, 301, 0.0, "プレシア", 10217, 5.0, 126102, "みんなも。せーぎも。\nクリアも。パパ、も。\nぜったい、たすける。\nみててね。お兄。", -285.0, 3);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (3, "2026/05/31 12:00:00", 1021703, "2030/01/01 14:59:59", 61, 201, 0.0, "クリア", 10217, 5.214, 126002, "癒しの力を使うこと…\nもう、ためらいません！\nモネちゃんやお兄さん…\nみんなに許してもらうためにも！", -285.0, 4);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, "2026/05/31 12:00:00", 1021704, "2030/01/01 14:59:59", 61, 102, 0.0, "リリ", 10217, 8.781, 139501, "ヴァルキュリア─皆様を助けたい\nという願いを、力にできるのなら…\nわたくしたちは、きっと誰にも\n負けません！　一意専心です…！", -285.0, 3);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, "2026/05/31 12:00:00", 1021705, "2030/01/01 14:59:59", 61, 202, 0.0, "クリア", 10217, 6.529, 139601, "このヴァルキュリアって職業、\nまるで天使みたいな格好ですよね\nうーん…『聖女』ちゃんって\n呼ばれるよりは、マシかな？", -285.0, 1);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (3, "2026/05/31 12:00:00", 1021706, "2030/01/01 14:59:59", 61, 302, 0.0, "プレシア", 10217, 3.195, 139701, "ばるきり。もーど。\nはね。まっしろ。\nはっぴーちゃんと。おなじ。\nいいかんじ。", -285.0, 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, "2026/06/30 12:00:00", 1021801, "2030/01/01 14:59:59", 61, 101, 0.0, "ルイズマリー", 10218, 12.43, 139902, "ダーリンと一緒に南の島で\nリゾート開発なんて夢みたい♪\nああ…幸せ、最高の夏だわ…\n触れたら爆発さえしなければ～…っ", -285.0, 3);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, "2026/06/30 12:00:00", 1021802, "2030/01/01 14:59:59", 61, 201, 0.0, "クレジッタ", 10218, 6.35, 140001, "青い空、白い雲…無人島リゾートで\n大儲けですわ～♪　こらこらそこ、\nイチャついてるんじゃないですのよ\n触れたらドカンですわよ、ドカン！", -285.0, 3);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, "2026/07/31 12:00:00", 1021901, "2030/01/01 14:59:59", 61, 101, 0.0, "フブキ", 10219, 10.23, 140102, "みんなはかわいいぼくを見られて、\nぼくはみんなからラヴをもらう♡\n最高のウィンウィンだよね、これ♡\nで、最後はお兄さんをドレーに…♡", -285.0, 5);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, "2026/07/31 12:00:00", 1021902, "2030/01/01 14:59:59", 61, 201, 0.0, "ヴァンピィ", 10219, 5.584, 140201, "けんぞくとたくさん遊ぶためにも、\nみんなからラヴをもらわなくちゃ♪\nバズっちゃおー作戦、\n一緒に考えてね！　けんぞくぅ♪", -285.0, 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, "2026/04/10 12:00:00", 2000001, "2030/01/01 14:59:59", 62, 1, 0.0, "カリン", 2, 3.414, 190801, "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください", -416.5, 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, "2026/04/10 12:00:00", 2000002, "2030/01/01 14:59:59", 62, 2, 0.0, "カリン", 2, 3.099, 190801, "ミッションをクリアして、\n報酬をゲットしましょう！", -416.5, 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, "2026/04/10 12:00:00", 2000003, "2030/01/01 14:59:59", 63, 3, 0.0, "カリン", 2, 2.801, 190801, "受け取ることができる\n報酬があるようです\n確認してみてください", -416.5, 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, "2026/04/10 12:00:00", 2000004, "2030/01/01 14:59:59", 63, 4, 0.0, "カリン", 2, 0.0, 190801, "報酬がもらえますよ！\nチェックしてみてください", -416.5, 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, "2026/04/10 12:00:00", 2000005, "2030/01/01 14:59:59", 64, 5, 0.0, "カリン", 2, 2.12, 190801, "ギルド管理協会です！\nイベント報酬券をお持ちでしたら、様々なアイテムと交換できますよ", -363.0, 1);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, "2026/04/10 12:00:00", 2000006, "2030/01/01 14:59:59", 64, 6, 0.0, "カリン", 2, 1.68, 190801, "お疲れさまです！\nこちらでイベント報酬券とアイテムを交換することができますよ", -363.0, 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, "2026/04/10 12:00:00", 2000007, "2030/01/01 14:59:59", 64, 7, 0.0, "カリン", 2, 2.33, 190801, "いつもありがとうございます！\n報酬交換ですか？\nでは、イベント報酬券とお引き換えいたしますね", -363.0, 1);
